<script setup lang="ts">import type{AdminAlert}from"~/composables/useAdminControlPlane";defineProps<{items:AdminAlert[]}>();const emit=defineEmits<{acknowledge:[id:string]}>();</script><template><section class="admin-panel"><header><div><h2>مرکز هشدار</h2><p>هشدارهای باز بر اساس شدت و زمان</p></div></header><div class="admin-alert-list"><article v-for="item in items" :key="item.id" :data-severity="item.severity"><span>{{item.severity==='critical'?'!':item.severity==='warning'?'△':'i'}}</span><div><b>{{item.title}}</b><p>{{item.description}}</p><small>{{item.source}} · {{item.occurrence_count.toLocaleString('fa-IR')}} رخداد</small></div><button v-if="item.state==='open'" class="button button-secondary" type="button" @click="emit('acknowledge',item.id)">تأیید و پیگیری</button><em v-else>در حال پیگیری</em></article></div></section></template>
